contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to forward to c.go
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract can forward the requested amount
        require(address(this).balance >= amount);

        // observe pre-call values
        address preOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint preCbalance = address(c).balance;

        bool reverted;
        // perform the state-changing call on c as a top-level statement
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe post-call values
        address postOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint postCbalance = address(c).balance;

        // General rule: if the call did not revert then owner unchanged and C's balance after the call is at most preCbalance + amount
        // (i.e., a successful go cannot create more Ether in C than what was sent)
        assert(reverted || (postOwner == preOwner && postCbalance <= preCbalance + amount));
    }

    receive() external payable {}
}

